export const KEYS = Object.keys(S);
export function fmtNum(lang, v, d) {
  return new Intl.NumberFormat(LOCALE[lang] || 'it-IT', { minimumFractionDigits: d, maximumFractionDigits: d }).format(v);
}
export function has(key) { return key in S; }
export function tr(lang, key, p = {}) {
  const row = S[key];
  if (!row) return key;
  const i = Math.max(0, ORDER.indexOf(lang));
  const s = row[i] || row[0];
  return s.replace(/\{(\w+)(?::(\d))?\}/g, (m, k, d) => (p[k] === undefined ? m : d !== undefined ? fmtNum(lang, Number(p[k]), +d) : String(p[k])));
}
export function detectLang(saved) {
  if (saved && LANGS[saved]) return saved;
  const prefs = (typeof navigator !== 'undefined' && (navigator.languages || [navigator.language])) || [];
  for (const l of prefs) { const k = String(l || '').slice(0, 2).toLowerCase(); if (LANGS[k]) return k; }
  return 'en';
}
export function checkTable() {
  const bad = [];
  for (const [k, row] of Object.entries(S)) {
    if (row.length !== 6 || row.some((x) => typeof x !== 'string' || !x.length)) bad.push(k);
    const ph = (x) => (x.match(/\{\w+(?::\d)?\}/g) || []).map((y) => y.replace(/:\d/, '')).sort().join();
    if (row.length === 6 && row.some((x) => ph(x) !== ph(row[0]))) bad.push(k + ' (segnaposto)');
  }
  return bad;
}
